const t=/\[Person:(\d*):([\w -]*)\]/gm,e=/\[Activity:(\d*):(.*)\]/gm,n=/\[Organization:(\d*):(.*)\]/gm,a="/person/show/",i="/organization/show/",o="/activites-de-recherche/fiche/",s={log(r){return this.organization(this.activity(this.person(r)))},person(r){return r.replace(t,'<a href="'+a+'$1" class="person">$2</a>')},activity(r){return r.replace(e,'<a href="'+o+'$1" class="person">$2</a>')},organization(r){return r.replace(n,'<a href="'+i+'$1" class="organization">$2</a>')}};export{s as t};
